/**
 * KS-879 — NO RAW CONTROL BYTE MAY BE COMMITTED ANYWHERE UNDER Blockchain/Dev.
 *
 * KS-847 established the rule and shipped a guard, but that guard walks
 * `services/auth/src` only — so `services/transfer` kept two raw NULs, and
 * nothing in the repo could see them. This is the same predicate over the
 * whole tree.
 *
 * ## Why a raw control byte matters more than it looks
 *
 * A raw NUL makes a file binary to text tooling, and the failure is SILENT:
 * grep produces no output, not "0 matches" — no count, exit 1. In one session
 * that single file produced three wrong or nearly-wrong readings:
 *
 *   1. KS-860's census: plain `grep` gives 77/70 where `git grep -a` gives
 *      78/71 — the census is only correct with `-a`.
 *   2. KS-860's diff: a real one-line change in that file was reported as
 *      `Bin 5581 -> 5594 bytes`, "0 insertions" — invisible to a reviewer.
 *   3. The arithmetic "55 files changed, 54 insertions", which looked like a
 *      miscount and was not.
 *
 * And while verifying the KS-879 fix itself, a `git diff -a | grep` pipeline
 * printed NOTHING — because the diff still carried the pre-image's raw byte,
 * so grep classified its own input as binary. The defect defeated the command
 * checking the fix for it. That is the shape being guarded against.
 *
 * ## Why the walk is safe to widen NOW
 *
 * Measured at `develop` 14914258c: of 1,240 tracked .ts/.js/.mjs/.tsx files
 * under Blockchain/Dev, exactly ONE carried a raw control byte. With that file
 * escaped the repo-wide count is zero, so this guard is green on day one. The
 * cheapest moment to widen a guard is while the tree is already clean.
 *
 * ## KS-886 — and now it IS repo-wide
 *
 * The first version walked `services/` and `packages/` only — 749 of the 1,242
 * files the sentence above counts — while the name said repo-wide and the
 * docblock censused the whole of Blockchain/Dev. The 493 outside the net
 * included all 148 under `tests/`, which is exactly where this class had
 * lived twice. The walk is now rooted at Blockchain/Dev itself, with the same
 * SKIP set and the same five extensions (`.ts .tsx .js .mjs .cjs` — `EXTS`
 * below; the prose used to list four). Re-measured at `0f69129b3` over that
 * set: 1,284 files, 12,758,153 bytes read, 0 raw control bytes. The floors in
 * the walk control are set from that census.
 *
 * ## Relationship to the KS-847 guard
 *
 * `services/auth/src/__tests__/ks847-no-raw-control-bytes.test.ts` stays where
 * it is. It is a fast self-scan that runs with auth's own suite, and it fails
 * closer to the author. This guard is the repo-wide net and supersedes its
 * SCOPE, not its existence. The overlap is deliberate: two cheap checks of the
 * same rule is not a cost worth optimising away.
 *
 * Every NUL a test needs is written as the six-character escape, or built with
 * `String.fromCharCode(0)`. The escape is IDENTICAL at runtime — the string
 * still contains U+0000 — so the raw byte buys nothing and costs the file's
 * readability to every text tool in the repo.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, existsSync, mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve, relative } from 'node:path';

/**
 * Locate the Dev root by walking up until `services/` and `packages/` are both
 * present. Same idiom as `ks727-errorhandler-class-guard.test.ts`,
 * `ks781-p3-3-body-parser-order.test.ts` and `ks860-…`, so the structural
 * guards root themselves identically however vitest is invoked.
 */
function findDevRoot(start: string): string {
  let dir = start;
  for (let i = 0; i < 10; i++) {
    if (existsSync(join(dir, 'services')) && existsSync(join(dir, 'packages'))) return dir;
    const parent = resolve(dir, '..');
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error(`[ks879 guard] could not locate the Dev root from ${start}`);
}

const DEV_ROOT = findDevRoot(process.cwd());

/** tab, LF, CR are legal text; every other C0 is not. DEL is not either. */
const ALLOWED_C0 = new Set([0x09, 0x0a, 0x0d]);

/**
 * The byte class the PRODUCT refuses, mirrored here: C0-minus-whitespace plus
 * DEL — the same widening KS-842 Q-3 made after a raw 0x7F was measured
 * invisible to a `b < 0x20` test.
 */
export function rawControlBytes(buf: Buffer): { offset: number; byte: number }[] {
  const out: { offset: number; byte: number }[] = [];
  for (let i = 0; i < buf.length; i++) {
    const b = buf[i];
    if ((b < 0x20 && !ALLOWED_C0.has(b)) || b === 0x7f) out.push({ offset: i, byte: b });
  }
  return out;
}

const SKIP_DIRS = new Set(['node_modules', 'dist', 'build', 'coverage', '.turbo']);
const EXTS = ['.ts', '.tsx', '.js', '.mjs', '.cjs'];

function sourceFiles(dir: string): string[] {
  const out: string[] = [];
  if (!existsSync(dir)) return out;
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, e.name);
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name)) out.push(...sourceFiles(full));
    } else if (EXTS.some((x) => e.name.endsWith(x))) {
      out.push(full);
    }
  }
  return out;
}

/**
 * KS-886: every offending byte under `root`, one line per byte, relative to
 * `root`. The 🔴 cell runs this over Blockchain/Dev; the regression cell runs
 * the SAME function over a scratch tree with a planted NUL, so the walk and
 * the predicate the guard actually uses are what the regression exercises.
 */
export function offendersUnder(root: string): string[] {
  // Bytes, not a string: reading as utf8 goes through a decoder that can
  // normalise or replace, and the claim is about what is ON DISK.
  const out: string[] = [];
  for (const f of sourceFiles(root)) {
    for (const { offset, byte } of rawControlBytes(readFileSync(f))) {
      out.push(`${relative(root, f)}: 0x${byte.toString(16).padStart(2, '0')} at byte ${offset}`);
    }
  }
  return out;
}

/** The set the guard walks — module-level so cells can pin what it reaches. KS-886: the whole Dev tree. */
const WALKED: readonly string[] = sourceFiles(DEV_ROOT);

// KS-886: the walk reads ~1,300 files / ~13 MB; on a loaded shared host that
// has exceeded vitest's 5 s default (measured 2026-09-13 at load average ~20).
// Wall-clock is not the property under test, so the two I/O cells carry a
// budget of their own.
const WALK_TIMEOUT_MS = 30_000;

describe('KS-879 — no raw control byte anywhere under Blockchain/Dev', () => {
  const files = WALKED;

  it('🔴 no raw C0 byte and no DEL appears in any source file under Blockchain/Dev', () => {
    const offenders = offendersUnder(DEV_ROOT);
    expect(
      offenders,
      'A raw control byte reached a committed file. grep will now skip that whole file ' +
        'SILENTLY — no output, not "0 matches" — so every sweep of this repo is blind to it, ' +
        'git reports its diffs as "Bin … bytes" with 0 insertions, and a reviewer cannot see ' +
        'the change. Write the byte as the six-character escape instead; it is identical at runtime.',
    ).toEqual([]);
  }, WALK_TIMEOUT_MS);

  it('CONTROL — the walk read the WHOLE Dev tree, so the case above is not "empty is empty"', () => {
    // KS-886: floors re-stated over the widened set (1,284 files / 12.8 MB at
    // 0f69129b3), with headroom for churn but well above the old two-root set
    // (798 files), so a walk that silently fell back to it reds here.
    expect(files.length, 'an empty walk passes every filter vacuously').toBeGreaterThan(1_000);
    const rel = files.map((f) => relative(DEV_ROOT, f));
    expect(rel.some((f) => f.startsWith('services/')), 'the walk reached services/').toBe(true);
    expect(rel.some((f) => f.startsWith('packages/')), 'the walk reached packages/').toBe(true);
    expect(rel.some((f) => f.startsWith('tests/')), 'the walk reached tests/').toBe(true);
    expect(rel.some((f) => f.startsWith('frontend/')), 'the walk reached frontend/').toBe(true);
    // Named files in two different services — a walk that silently reached only
    // one service cannot pass this.
    expect(
      rel.some((f) => f.includes(join('services', 'transfer'))),
      'and it reached services/transfer, the file this ticket is about',
    ).toBe(true);
    expect(
      rel.some((f) => f.includes(join('services', 'auth'))),
      'and it reached services/auth, where the class was first found',
    ).toBe(true);
    const bytes = files.reduce((n, f) => n + readFileSync(f).length, 0);
    expect(bytes, 'and it read real bytes, not empty handles').toBeGreaterThan(5_000_000);
  }, WALK_TIMEOUT_MS);

  it('CONTROL — the predicate DOES fire, so a clean result means something', () => {
    const withNul = Buffer.concat([Buffer.from('abc'), Buffer.from([0x00]), Buffer.from('def')]);
    expect(rawControlBytes(withNul)).toEqual([{ offset: 3, byte: 0x00 }]);
    const withDel = Buffer.concat([Buffer.from('abc'), Buffer.from([0x7f]), Buffer.from('def')]);
    expect(rawControlBytes(withDel), 'DEL counts too — KS-842 Q-3').toEqual([
      { offset: 3, byte: 0x7f },
    ]);
    // Two bytes in one file are both reported — the ks474 shape exactly.
    const two = Buffer.concat([
      Buffer.from('a'),
      Buffer.from([0x00]),
      Buffer.from('b'),
      Buffer.from([0x00]),
    ]);
    expect(rawControlBytes(two).map((x) => x.offset)).toEqual([1, 3]);
  });

  it('CONTROL — legal whitespace does NOT trip it, or every file would be an offender', () => {
    expect(rawControlBytes(Buffer.from('a\tb\nc\rd'))).toEqual([]);
  });

  it('E1 CONTROL — the ESCAPED spelling is not a raw byte, and the escape ITSELF evaluates to U+0000', () => {
    // Both halves of the fix in one cell: the source stays plain ASCII, and the
    // runtime value is unchanged. If the escape did not produce U+0000 the
    // ks474 fixture would silently stop testing the NUL path it exists for.
    //
    // KS-885: this used to build the string with `String.fromCharCode(0)` and
    // assert it carried U+0000 — true by construction of that line, a tautology
    // about JavaScript. The bridging claim, that the six-character escape
    // EVALUATES to U+0000, was asserted nowhere, and the ks474 fixture could
    // stop carrying a NUL with every suite green. The literal below IS the
    // escape, written as its six characters (the way the KS-847 guard does it).
    const escaped = 'doc\u0000bad';
    expect(escaped.charCodeAt(3), 'the six-character escape really evaluates to U+0000').toBe(0);
    expect(escaped.length, 'and it is one code unit at runtime, not six characters').toBe(7);
    const sourceSpelling = `const x = 'doc\\u0000bad';`;
    expect(
      rawControlBytes(Buffer.from(sourceSpelling, 'utf8')),
      'yet the SOURCE spelling is plain ASCII',
    ).toEqual([]);
  });
});

describe('KS-885 — the ks474 fixture still carries the NUL its cells exist for', () => {
  // The fix shape above proves the ESCAPE evaluates to U+0000 — inside this
  // file. The ticket's regression is about ANOTHER file: respell both sites of
  // the ks474 fixture so the string carries no U+0000, and "at least one cell
  // must fail". No cell here read that file, so nothing could. This cell does:
  // read-only, anchored on the literal (never a line number), with an
  // exists-control so a moved file is loud rather than vacuous. It is the one
  // cross-package read this guard has, and it is here on purpose.
  const KS474 = join(
    DEV_ROOT, 'services', 'transfer', 'src', '__tests__', 'ks474-delegation-document-id.test.ts',
  );
  // The needles are spelled with a doubled backslash in THIS source so that
  // they evaluate to the six-character escape text, not to U+0000.
  const SIX_CHAR = "'doc\\u0000bad'";
  const DOUBLED = "'doc\\\\u0000bad'";

  it('E2 both ks474 documentId sites carry the six-character escape, and neither carries the doubled spelling', () => {
    expect(existsSync(KS474), `${relative(DEV_ROOT, KS474)} must exist — the fixture this guard was written for`).toBe(true);
    const src = readFileSync(KS474, 'utf8');
    expect(src.split(SIX_CHAR).length - 1, 'two sites spelled as the six-character escape').toBe(2);
    expect(src.split(DOUBLED).length - 1, 'and none spelled with a doubled backslash').toBe(0);
    // Controls on the needles themselves: they are inert text here, not NULs.
    expect(SIX_CHAR.length, "'doc' + the six-character escape + 'bad', quoted").toBe(14);
    expect(rawControlBytes(Buffer.from(src, 'utf8'))).toEqual([]);
  });
});

describe('KS-886 — the walk is repo-wide, as the name and the docblock say', () => {
  it('F1 the walk reaches tests/ — by a NAMED file, so a walk that silently stayed under services/ + packages/ reds', () => {
    // tests/ is where this class has lived twice (KS-847, KS-879), and it was
    // outside the net: 148 files, none walked.
    const rel = WALKED.map((f) => relative(DEV_ROOT, f));
    expect(rel, 'tests/ is walked').toContain(join('tests', 'admin-crud-test-robust.spec.ts'));
    expect(rel, 'frontend/ is walked').toContain(join('frontend', 'verifier', 'src', 'App.tsx'));
    expect(rel, 'scripts/ is walked').toContain(join('scripts', 'check-port-crossover.mjs'));
  });

  it('F2 REGRESSION — a raw NUL planted under a scratch tests/ is caught by the SAME walk-and-predicate the 🔴 cell uses', () => {
    // The ticket's regression: "a planted raw NUL anywhere in the chosen set
    // must be caught". Exercised through `offendersUnder`, not a re-implemented
    // walk, so this cannot agree with the guard for the wrong reason.
    const scratch = mkdtempSync(join(tmpdir(), 'ks886-'));
    try {
      const dir = join(scratch, 'tests');
      mkdirSync(dir, { recursive: true });
      writeFileSync(join(dir, 'clean.spec.ts'), 'export const ok = 1;\n');
      // CONTROL first: a clean scratch tree reports nothing.
      expect(offendersUnder(scratch)).toEqual([]);
      writeFileSync(
        join(dir, 'planted.spec.ts'),
        Buffer.concat([Buffer.from("const bad = 'doc"), Buffer.from([0x00]), Buffer.from("bad';\n")]),
      );
      expect(offendersUnder(scratch), 'the planted byte must be named, with its offset').toEqual([
        `${join('tests', 'planted.spec.ts')}: 0x00 at byte 16`,
      ]);
    } finally {
      rmSync(scratch, { recursive: true, force: true });
    }
  });
});
